db.Highschooler.aggregate([
  {
    $match: {
      "name": "Kyle"
    }
  },
  {
    $lookup: {
      from: "Friend",
      localField: "ID",
      foreignField: "student_id",
      as: "friends"
    }
  },
  {
    $unwind: "$friends"
  },
  {
    $lookup: {
      from: "Highschooler",
      localField: "friends.friend_id",
      foreignField: "ID",
      as: "friend_hs"
    }
  },
  {
    $unwind: "$friend_hs",
    $project: {
      _id: 0,
      name: "$friend_hs.name"
    }
  }
])

db.tracks.aggregate([
  {"$match": {"genre_id": {"$in": [1, 3]}}, // Assuming Genre ID 1 for Latin and Genre ID 3 for Pop
  {"$group": {"_id": null, "avg_duration": {"$avg": "$milliseconds"}}}
])

db.Tracks.aggregate([
    {"$match": {"genre_id": {"$in": [1, 2]}},  # genre_ids for Latin and Pop
    {"$group": {"_id": None, "avg_duration_ms": {"$avg": "$Milliseconds"}}},
    {"$project": {"avg_duration_ms": 1}}
])
